const total = Number($('Generar pedido').first().json.total_pago || 0);
const usuario = $json;
const puntosActuales = Number(usuario.puntos_lealtad || 0);
const PESOS_POR_PUNTO = 5000;
const puntosGanados = Math.floor(total / PESOS_POR_PUNTO);
const puntosTotales = puntosActuales + puntosGanados;
return [{ json: {
  id_usuario: $('Generar pedido').first().json.id_usuario,
  puntosGanados,
  puntosTotales
} }];

const productos = $input.all();
const disponibles = productos.filter(item => Number(item.json.stock || 0) > 0);

const inline_keyboard = disponibles.map(item => {
  const p = item.json;
  return [{
    text: `${p.nombre} - $${Number(p.precio).toLocaleString("es-CO")}`,
    callback_data: `prod:${p.id_producto}`
  }];
});

return [{
  json: {
    mensaje: disponibles.length ? "Elige un producto:" : "⚠️ No hay disponibles.",
    inline_keyboard
  }
}];

const producto = $json;
const cantidad = 1;
const mensaje = `\ud83d\uded2 *${producto.nombre}*\n\ud83d\udcb2 $${Number(producto.precio).toLocaleString("es-CO")}\n\ud83d\udce6 Stock disponible: ${producto.stock}\n\nCantidad: *${cantidad}*`;
const inline_keyboard = [
  [
    { text: "\u2796", callback_data: `qty:${producto.id_producto}:${cantidad}:dec` },
    { text: `${cantidad}`, callback_data: `qty:${producto.id_producto}:${cantidad}:noop` },
    { text: "\u2795", callback_data: `qty:${producto.id_producto}:${cantidad}:inc` }
  ],
  [
    { text: "\ud83d\uded2 Agregar al carrito", callback_data: `qty:${producto.id_producto}:${cantidad}:add` }
  ]
];
return [{ json: { mensaje, inline_keyboard } }];

const data = $('Telegram Trigger1').first().json.callback_query.data;
const [, id_producto, cantidadActual, accion] = data.split(":");
let cantidad = Number(cantidadActual);
if (accion === "inc") cantidad = cantidad + 1;
if (accion === "dec") cantidad = Math.max(1, cantidad - 1);
return [{ json: { id_producto, cantidad, accion } }];

const producto = $('Buscar producto para cantidad').first().json;
const cantidad = $('Parsear callback cantidad').first().json.cantidad;
const sesion = $json;
let carrito = [];
try { carrito = JSON.parse(sesion.carrito_temporal || "[]"); } catch (e) { carrito = []; }
const existente = carrito.find(i => i.id_producto === producto.id_producto);
if (existente) { existente.cantidad += cantidad; }
else { carrito.push({ id_producto: producto.id_producto, nombre: producto.nombre, precio: Number(producto.precio), cantidad }); }
let total = 0;
let resumen = "\ud83d\uded2 *Tu carrito:*\n\n";
for (const item of carrito) {
  const subtotal = item.precio * item.cantidad;
  total += subtotal;
  resumen += `\u2022 ${item.nombre} x${item.cantidad} \u2014 $${subtotal.toLocaleString("es-CO")}\n`;
}
resumen += `\n*Total: $${total.toLocaleString("es-CO")}*`;
return [{ json: { carrito_json: JSON.stringify(carrito), mensaje: resumen } }];

const producto = $('Buscar producto para cantidad').first().json;
const cantidad = $('Parsear callback cantidad').first().json.cantidad;
const mensaje = `\ud83d\uded2 *${producto.nombre}*\n\ud83d\udcb2 $${Number(producto.precio).toLocaleString("es-CO")}\n\ud83d\udce6 Stock disponible: ${producto.stock}\n\nCantidad: *${cantidad}*`;
const inline_keyboard = [
  [
    { text: "\u2796", callback_data: `qty:${producto.id_producto}:${cantidad}:dec` },
    { text: `${cantidad}`, callback_data: `qty:${producto.id_producto}:${cantidad}:noop` },
    { text: "\u2795", callback_data: `qty:${producto.id_producto}:${cantidad}:inc` }
  ],
  [
    { text: "\ud83d\uded2 Agregar al carrito", callback_data: `qty:${producto.id_producto}:${cantidad}:add` }
  ]
];
return [{ json: { mensaje, inline_keyboard } }];

const sesion = $('Leer carrito para confirmar').first().json;
const menu = $input.all().map(i => i.json);
let carrito = [];
try { carrito = JSON.parse(sesion.carrito_temporal || "[]"); } catch (e) { carrito = []; }

if (carrito.length === 0) {
  return [{ json: { valido: false, carritoVacio: true, total: 0, items: [], problemas: "" } }];
}

let total = 0;
let problemas = [];
const items = [];

for (const item of carrito) {
  const productoMenu = menu.find(p => p.id_producto === item.id_producto);
  const stockDisponible = productoMenu ? Number(productoMenu.stock) : 0;
  if (!productoMenu || stockDisponible < item.cantidad) {
    problemas.push(`${item.nombre} (disponible: ${stockDisponible}, pedido: ${item.cantidad})`);
    continue;
  }
  total += item.precio * item.cantidad;
  items.push({ id_producto: item.id_producto, nombre: item.nombre, cantidad: item.cantidad, precio: item.precio, stockRestante: stockDisponible - item.cantidad });
}

return [{ json: { valido: problemas.length === 0 && items.length > 0, carritoVacio: false, total, items, problemas: problemas.join(", ") } }];

const data = $json;
const fecha = new Date();
const id_pedido = "PED-" + fecha.getTime();
return [{ json: {
  id_pedido,
  id_usuario: $('Telegram Trigger1').first().json.callback_query.message.chat.id,
  detalles_pedido: JSON.stringify(data.items),
  total_pago: data.total,
  estado: "Recibido",
  fecha: fecha.toISOString().split("T")[0],
  hora: fecha.toTimeString().split(" ")[0],
  items: data.items
} }];

const pedidos = $input.all().map(i => i.json);
const activos = pedidos.filter(p => p.estado && p.estado !== "Entregado");
let mensaje;
if (activos.length === 0) {
  mensaje = "\ud83d\udce6 No tienes pedidos activos en este momento.";
} else {
  const pedido = activos[activos.length - 1];
  const emojis = { "Recibido": "\ud83c\udd95", "Preparacion": "\ud83d\udc68\u200d\ud83c\udf73", "Preparaci\u00f3n": "\ud83d\udc68\u200d\ud83c\udf73", "En camino": "\ud83d\udef5", "Entregado": "\u2705" };
  const emoji = emojis[pedido.estado] || "\ud83d\udce6";
  mensaje = `${emoji} *Pedido ${pedido.id_pedido}*\n\nEstado: *${pedido.estado}*\n\ud83d\udcb0 Total: $${Number(pedido.total_pago).toLocaleString("es-CO")}\n\ud83d\udcc5 ${pedido.fecha} ${pedido.hora}`;
}
return [{ json: { mensaje } }];

const pedidos = $input.all().map(i => i.json);
let mensaje;
if (pedidos.length === 0) {
  mensaje = "\ud83d\udccb A\u00fan no tienes pedidos en tu historial.";
} else {
  const ordenados = [...pedidos].sort((a, b) => {
    const fa = new Date(`${a.fecha}T${a.hora}`);
    const fb = new Date(`${b.fecha}T${b.hora}`);
    return fb - fa;
  }).slice(0, 5);
  mensaje = "\ud83d\udccb *Tus \u00faltimos pedidos:*\n\n";
  for (const p of ordenados) {
    mensaje += `\u2022 ${p.id_pedido} \u2014 $${Number(p.total_pago).toLocaleString("es-CO")} \u2014 ${p.estado} (${p.fecha})\n`;
  }
}
return [{ json: { mensaje } }];

const data = $('Telegram Trigger1').first().json.callback_query.data;
const [, id_pedido, codigo] = data.split(":");
const mapa = { prep: "Preparaci\u00f3n", camino: "En camino", entregado: "Entregado" };
const estado = mapa[codigo] || codigo;
return [{ json: { id_pedido, estado } }];

const usuario = $json;
const nombre = usuario.nombre_completo || "usuario";
const puntos = Number(usuario.puntos_lealtad || 0);
const mensaje = `Hola ${nombre}, actualmente tienes \ud83c\udfc6 ${puntos} puntos acumulados. \u00a1Sigue comprando para canjear premios!`;
return [{ json: { mensaje } }];
